MC.registerPack({"id":"valk","cards":[{"id":"25001a","name":"발키리","en":"* Valkyrie","type":"hero","enc":false,"unique":true,"hp":12,"atk":2,"thw":1,"def":1,"hs":5,"tr":["ASGARD","AVENGER"],"traits":["아스가르드","어벤저"],"text":"죽음 감지 — <b>히어로 행동</b>: 따로 놓아둔 죽음의 광채 업그레이드를 당신의 손에 있는 것처럼 플레이합니다."},{"id":"25001b","name":"브룬힐데","en":"* Brunnhilde","type":"alter","enc":false,"unique":true,"hp":12,"rec":4,"hs":6,"tr":["ASGARD"],"traits":["아스가르드"],"text":"<b>사전 준비:</b> 죽음의 광채 업그레이드를 게임 밖에 따로 놓아둡니다.\n\"오늘은 아니다.\" — <b>행동</b>: 죽음의 광채를 장착 해제하고 게임 밖에 따로 놓아둡니다."},{"id":"25002","name":"죽음의 광채","en":"Death-Glow","type":"upgrade","enc":false,"unique":false,"cost":1,"cls":"Hero","tr":["CONDITION"],"traits":["상태"],"text":"적 하나에 장착합니다.\n<b>강제 난입</b>: 장착된 적이 격파될 때, 이 카드를 게임 밖에 따로 놓아둡니다. 발키리가 그 적을 격파했다면, 그녀를 준비합니다."},{"id":"25003","name":"애너벨 리그스","en":"* Annabelle Riggs","type":"ally","enc":false,"unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"G","cls":"Hero","tr":["CIVILIAN"],"traits":["시민"],"text":"<b>일상 행동</b>: 애너벨 리그스를 소진 → 당신의 덱 맨 위 카드 5장에서 발키리 카드 1장을 찾아 당신의 손에 더함. 나머지는 당신의 덱에 섞어 넣음."},{"id":"25004","name":"발할라","en":"* Valhalla","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Hero","tr":["ASGARD","LOCATION"],"traits":["아스가르드","장소"],"text":"<b>반응</b>: 발키리가 죽음의 광채가 장착된 적을 공격하여 격파한 후, 발할라를 소진 → 카드 1장을 뽑고 발키리가 입은 피해 1점을 치료."},{"id":"25005","name":"발키리의 창","en":"* Valkyrie's Spear","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"R","cls":"Hero","tr":["ASGARD","WEAPON"],"restricted":1,"traits":["아스가르드","무기"],"text":"한정.\n발키리는 방어 +1을 받습니다(죽음의 광채가 장착된 적의 공격을 방어하는 동안에는 대신 방어 +2)."},{"id":"25006","name":"드래곤팽","en":"* Dragonfang","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"R","cls":"Hero","tr":["ASGARD","WEAPON"],"restricted":1,"traits":["아스가르드","무기"],"text":"한정.\n발키리는 공격 +1을 받습니다(죽음의 광채가 장착된 적을 공격하는 동안에는 대신 공격 +2)."},{"id":"25007","name":"아라곤","en":"* Aragorn","type":"upgrade","enc":false,"unique":true,"cost":2,"res":"B","cls":"Hero","tr":["ASGARD","CREATURE"],"traits":["아스가르드","괴수"],"text":"당신은 생명력 +4를 받고 [[공중]] 특성을 얻습니다."},{"id":"25008","name":"발키리오르의 비행","en":"Flight of the Valkyrior","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":[],"traits":[],"text":"<b>반응</b>: 죽음의 광채가 장착된 적이 격파된 후, 발키리오르의 비행을 버림 → 음모 하나에서 위협을 5만큼 제거."},{"id":"25009","name":"발할라 방문","en":"Visit Valhalla","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Hero","tr":[],"traits":[],"text":"<b>일상 행동</b>: 당신의 버린 더미에서 발키리 카드 1장을 당신의 손으로 되돌립니다."},{"id":"25010","name":"전사자를 고르는 자","en":"Chooser of the Slain","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Hero","tr":[],"traits":[],"text":"<b>히어로 행동</b>: 조우 덱과 버린 조우 더미에서 하수인 1장을 찾아 당신과 교전 중인 채로 플레이 영역에 내려놓음 → 카드 2장을 뽑음."},{"id":"25011","name":"방패의 처녀","en":"Shieldmaiden","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["DEFENSE"],"traits":["방어"],"text":"<b>히어로 난입</b><i>(방어)</i>: 죽음의 광채가 장착된 적이 공격할 때, 발키리를 소진하지 않고 방어자로 선언합니다. 그녀는 이번 공격 동안 방어 +2를 받습니다."},{"id":"25012","name":"덤벼라!","en":"Have at Thee!","type":"event","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Hero","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b>(공격): 적 하나에게 피해 7점을 입힙니다. 그 적에게 죽음의 광채가 장착되어 있다면, 이 공격은 압살을 얻습니다."},{"id":"25013","name":"토르","en":"* Thor","type":"ally","enc":false,"sub":"오딘슨","unique":true,"hp":3,"atk":3,"atkStar":true,"atkCons":2,"thw":1,"thwStar":true,"cost":3,"res":"Y","cls":"Aggression","tr":["ASGARD","AVENGER"],"toughness":1,"traits":["아스가르드","어벤저"],"text":"강인.\n<b>난입</b>: 토르가 플레이어와 교전 중인 하수인을 공격할 때, [energy] 자원을 소모 → 그 플레이어와 교전 중인 각 하수인을 상대로 이 공격을 해결(당신이 선택한 순서대로)."},{"id":"25014","name":"스로그","en":"* Throg","type":"ally","enc":false,"sub":"퍼들걸프","unique":true,"hp":2,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"Y","cls":"Aggression","tr":["ASGARD","GUARDIAN"],"traits":["아스가르드","가디언"],"text":"<b>반응</b>: 스로그가 플레이 영역에 들어온 후, 당신이 하수인과 교전 중이라면 그에게 강인함 상태 카드를 줍니다."},{"id":"25015","name":"안젤라","en":"* Angela","type":"ally","enc":false,"sub":"알드리프 오딘스도티르","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":0,"thwStar":true,"cost":0,"res":"B","cls":"Aggression","tr":["ASGARD","GUARDIAN"],"traits":["아스가르드","가디언"],"text":"<b>강제 반응</b>: 안젤라가 당신의 조종하에 플레이 영역에 들어온 후, 조우 덱 맨 위 카드 10장에서 하수인 1장을 찾아 당신과 교전 중인 채로 플레이 영역에 내려놓습니다. 조우 덱을 섞습니다. 이렇게 플레이 영역에 내려놓은 하수인이 없다면, 안젤라를 버립니다.","link":"18011"},{"id":"25016","name":"영웅의 전당","en":"* Hall of Heroes","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Aggression","tr":["ASGARD","LOCATION"],"traits":["아스가르드","장소"],"text":"<b>반응:</b> 당신이 하수인을 격파한 후, 이 카드에 영광 카운터를 1만큼 놓습니다.\n<b>일상 행동:</b> 영웅의 전당을 소진하고 이 카드에서 영광 카운터를 3만큼 제거 → 카드 3장을 뽑습니다.","link":"06017"},{"id":"25017","name":"격투 훈련","en":"Combat Training","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Aggression","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신의 히어로가 공격 +1을 받습니다.","link":"01057"},{"id":"25018","name":"재빠른 일격","en":"Quick Strike","type":"event","enc":false,"unique":false,"cost":2,"res":"R","cls":"Aggression","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 당신 히어로의 공격 수치만큼 피해를 입힙니다."},{"id":"25019","name":"문제를 박살 내라","en":"Smash the Problem","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Aggression","tr":["THWART"],"traits":["저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 당신의 히어로를 소진 → 음모 하나에서 당신의 히어로의 공격 수치만큼 위협을 제거."},{"id":"25020","name":"최선의 방어는…","en":"The Best Defense...","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Aggression","tr":["DEFENSE"],"traits":["방어"],"text":"<b>히어로 난입</b><i>(방어)</i>: 당신의 히어로가 공격을 방어할 때, 이번 공격 동안 방어 수치 대신 공격 수치를 사용합니다."},{"id":"25021","name":"대담함","en":"Audacity","type":"resource","enc":false,"unique":false,"res":"G","cls":"Aggression","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.\n<b>히어로 반응</b>: 당신이 이 카드를 소모한 후, 빌런에게 피해 1점을 입힙니다.","link":"21046"},{"id":"25022","name":"용맹의 힘","en":"The Power of Aggression","type":"resource","enc":false,"unique":false,"res":"G","cls":"Aggression","tr":[],"maxDeck":2,"traits":[],"text":"덱마다 최대 2장.\n용맹<i>(빨간색)</i> 카드에 이 카드를 비용으로 지불하는 한, 이 카드가 생성하는 자원은 2배가 됩니다.","link":"01055"},{"id":"25023","name":"비프로스트","en":"* The Bifrost","type":"support","enc":false,"unique":true,"cost":1,"res":"Y","cls":"Basic","tr":["ASGARD","LOCATION"],"traits":["아스가르드","장소"],"text":"당신의 아이덴티티가 [[아스가르드]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>행동</b>: 비프로스트를 소진 → 당신의 덱에서 [[아스가르드]] 동료 1장을 찾아 플레이 <i>(비용을 지불함)</i>. 당신의 덱을 섞음."},{"id":"25024","name":"신과 같은 체력","en":"Godlike Stamina","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Basic","tr":[],"traits":[],"text":"당신의 아이덴티티가 [[아스가르드]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>행동</b>: 당신의 아이덴티티가 입은 피해 2점을 치료합니다. 당신의 아이덴티티에서 상태 카드 1장을 버려도 됩니다."},{"id":"25025","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"25026","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"25027","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"25028","name":"아더월드의 분란","en":"Trouble in Otherworld","type":"obligation","enc":true,"set":"Valkyrie","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>브룬힐데 플레이어에게 이 카드를 줍니다.</i></b>\n발키리는 죽음의 광채가 장착된 적을 공격할 수 없습니다.\n<b>일상 행동</b>: [energy][mental] 자원을 소모 → 아더월드의 분란을 게임에서 제거."},{"id":"25029","name":"인챈트리스","en":"* Enchantress","type":"minion","enc":true,"set":"Valkyrie Nemesis","unique":true,"hp":5,"atk":1,"sch":2,"boost":2,"tr":["ASGARD","ELITE"],"nemesis":true,"traits":["아스가르드","간부"],"text":"<b>공개될 때</b>: 조우 덱, 버린 조우 더미, 따로 놓아둔 영역에서 유혹당함 1장을 찾아 당신의 아이덴티티에 장착합니다. <i>(섞습니다.)</i>"},{"id":"25030","name":"강력한 마법","en":"Powerful Enchantments","type":"side","enc":true,"set":"Valkyrie Nemesis","unique":false,"boost":2,"start":2,"accel":1,"tr":[],"hinder":1,"hinderStar":true,"traits":[],"text":"교란 1[per_hero].\n플레이어는 아군 캐릭터에 장착된 장착 카드를 버릴 수 없습니다."},{"id":"25031","name":"현혹","en":"Beguiled","type":"attachment","enc":true,"set":"Enchantress","unique":false,"boost":1,"tr":["CONDITION"],"traits":["상태"],"text":"장착된 동료는 문구 상자가 비어 있는 [[매혹]] 하수인으로 취급합니다.\n장착된 하수인의 음모는 인쇄된 저지 수치와 같으며, 그 하수인은 부수적 피해를 입지 않습니다.\n<b>공개될 때</b>: 현혹이 장착되지 않은 동료 중 비용이 가장 높은 동료에게 장착합니다. 장착된 동료는 자신의 조종자와 교전합니다. 그렇지 않다면, 이 카드는 쇄도를 얻습니다.","link":"21178"},{"id":"25032","name":"유혹당함","en":"Seduced","type":"attachment","enc":true,"set":"Enchantress","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"당신의 아이덴티티에 장착합니다.\n당신은 기본 공격을 하거나 [[공격]] 이벤트를 플레이할 수 없습니다.\n<b>일상 행동</b>: [energy][mental] 자원을 소모 → 이 카드를 버림.","link":"21179"},{"id":"25033","name":"해결사들","en":"Problem Solvers","type":"event","enc":false,"unique":false,"cost":4,"res":"R","cls":"Justice","tr":["THWART"],"alliance":1,"traits":["저지"],"text":"동맹.\n<b>히어로 행동</b><i>(저지)</i>: [[어벤저]] 캐릭터 하나와 [[가디언]] 캐릭터 하나를 소진 → 각 음모에서 위협을 X만큼 제거. X는 그 캐릭터들의 저지 수치의 합과 같음."},{"id":"25034","name":"통솔 훈련","en":"Leadership Training","type":"support","enc":false,"unique":false,"cost":1,"res":"B","cls":"Leadership","tr":["CONDITION"],"uses":{"n":2,"kind":"training"},"maxDeck":2,"traits":["상태"],"text":"덱마다 최대 2장. 사용(훈련 카운터 2).\n<b>일상 행동</b>: 이 카드를 소진하고 이 카드에서 훈련 카운터를 1만큼 제거 → 당신의 버린 더미에서 통솔(파란색) 이벤트 1장을 선택해 당신의 덱에 섞어 넣음."},{"id":"25035","name":"예측","en":"Anticipation","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Protection","tr":["PREPARATION"],"maxPer":1,"traits":["대비"],"text":"플레이어마다 최대 1장.\n<b>히어로 난입</b>: 당신이 하수인과 교전에 돌입할 때, 이 카드를 버림 → 당신의 히어로를 준비."},{"id":"25036","name":"우주 동맹","en":"Cosmic Alliance","type":"event","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Basic","tr":[],"alliance":1,"traits":[],"text":"동맹. <i>(플레이어들은 이 카드의 비용을 함께 지불할 수 있습니다.)</i>\n<b>히어로 행동</b>: [[어벤저]] 캐릭터 하나와 [[가디언]] 캐릭터 하나를 선택 → 그 캐릭터들을 각각 준비."}]});
